.sheet-scrim { position: fixed; inset: 0; background: rgba(0,0,0,.5); }
.sheet {
  position: fixed; left: 0; right: 0; bottom: 0;
  padding: 8px 16px calc(16px + env(safe-area-inset-bottom));
  background: #fff; color: #0a0a0a;
  border-radius: 20px 20px 0 0;
  box-shadow: 0 -12px 32px -8px rgba(0,0,0,.25);
  max-height: 90vh; overflow: auto;
}
.sheet__handle { width: 36px; height: 4px; margin: 4px auto 12px; border-radius: 2px; background: #a3a3a3; }
.sheet__title { margin: 0 0 8px; font-size: 18px; }
.sheet__list { list-style: none; margin: 0; padding: 0; }
.sheet__list button { width: 100%; min-height: 48px; text-align: left; border: 0; border-bottom: 1px solid #e5e5e5; background: none; font: 500 16px/1 inherit; color: inherit; cursor: pointer; }
.sheet :focus-visible { outline: 2px solid #0a0a0a; outline-offset: -2px; }
